ilable right now.'=>'Vyhledávání teď není k dispozici.','No products found.'=>'Nebyly nalezeny žádné produkty.','No products found for “%s”.'=>'Pro „%s“ nebyly nalezeny žádné produkty.','Nothing found for “%s”.'=>'Pro „%s“ nebylo nic nalezeno.','Search products…'=>'Hledat produkty…','Close search'=>'Zavřít vyhledávání','Product results'=>'Nalezené produkty','Recent searches'=>'Nedávno hledané','Clear'=>'Vymazat','Start typing to search products…'=>'Začněte psát a vyhledejte produkty…','Sale'=>'Sleva','Out of stock'=>'Není skladem','Pages & posts'=>'Stránky a příspěvky','a website page, shown on a search resultPage'=>'Stránka','a blog post, shown on a search resultArticle'=>'Článek','unit: milliseconds%s ms'=>'%s ms','Powered by %s'=>'Používá %s','Page %1$s of %2$s'=>'Stránka %1$s z %2$s','← Prev'=>'← Předchozí','Next →'=>'Další →','button labelSearch'=>'Hledat','%s product found.'=>'Nalezen %s produkt.' . "\0" . 'Nalezeny %s produkty.' . "\0" . 'Nalezeno %s produktů.','See all %s result →'=>'Zobrazit %s výsledek →' . "\0" . 'Zobrazit všechny %s výsledky →' . "\0" . 'Zobrazit všech %s výsledků →','%1$s result for “%2$s”'=>'%1$s výsledek pro „%2$s“' . "\0" . '%1$s výsledky pro „%2$s“' . "\0" . '%1$s výsledků pro „%2$s“','%s result'=>'%s výsledek' . "\0" . '%s výsledky' . "\0" . '%s výsledků']];